import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, Easing, spring } from '../remotionShim';
{/* Start Google Fonts Loader */ }
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */ }



export type CalorieCounterProps = Record<string, any>;

const CalorieCounter: React.FC<CalorieCounterProps> = ({
  backgroundColor = "#111111",
  transparentBackground = true,
  durationInSeconds = 5,
  targetCalories = 2450,
  label = "DAILY INTAKE",
  accentColor = "#FF6B6B",
  textColor = "#ffffff",
  ringRadius = 250,
}) => {
  useFontLoader(["Inter", "Oswald"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Logic to prevent parser errors
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;
  
  // Animation Parameters
  const animationDurationFrames = Math.floor(durationInSeconds * fps);
  
  // Main Eased Progress (0 to 1)
  const progress = interpolate(
    frame,
    [0, animationDurationFrames],
    [0, 1],
    {
      easing: Easing.out(Easing.exp),
      extrapolateRight: "clamp",
    }
  );

  // Entrance Spring
  const scale = spring({
    frame,
    fps,
    config: {
      damping: 15,
      mass: 0.5,
    },
  });

  // Calculate Values
  const currentCalories = Math.round(progress * targetCalories);
  
  // SVG Ring Calculations
  const strokeWidth = ringRadius * 0.12; // Responsive stroke width
  const normalizedRadius = ringRadius - strokeWidth * 0.5;
  const circumference = normalizedRadius * 2 * Math.PI;
  const strokeDashoffset = circumference - progress * circumference;

  const containerStyle: React.CSSProperties = {
    display: "flex",
    justifyContent: "center",
    alignItems: "center",
    width: "100%",
    height: "100%",
    backgroundColor: bgColor,
    fontFamily: "'Inter', sans-serif",
    transition: "none",
  };

  const textContainerStyle: React.CSSProperties = {
    position: "absolute",
    display: "flex",
    flexDirection: "column",
    alignItems: "center",
    justifyContent: "center",
    textAlign: "center",
    transition: "none",
  };

  return (
    <AbsoluteFill style={containerStyle}>
      <div style={{ transform: `scale(${scale})`, position: "relative", transition: "none" }}>
        {/* SVG Ring */}
        <svg
          height={ringRadius * 2}
          width={ringRadius * 2}
          style={{ transform: "rotate(-90deg)", transition: "none" }}
        >
          {/* Background Track */}
          <circle
            stroke={textColor}
            strokeWidth={strokeWidth}
            strokeOpacity={0.15}
            fill="transparent"
            r={normalizedRadius}
            cx={ringRadius}
            cy={ringRadius}
            style={{ transition: "none" }}
          />
          {/* Progress Ring */}
          <circle
            stroke={accentColor}
            strokeWidth={strokeWidth}
            strokeDasharray={`${circumference} ${circumference}`}
            style={{ 
              strokeDashoffset, 
              transition: "none",
              strokeLinecap: "round"
            }}
            fill="transparent"
            r={normalizedRadius}
            cx={ringRadius}
            cy={ringRadius}
          />
        </svg>

        {/* Center Text */}
        <div style={{
          ...textContainerStyle,
          top: 0,
          left: 0,
          right: 0,
          bottom: 0,
        }}>
          <h1 style={{
            fontFamily: "'Oswald', sans-serif",
            fontSize: `${ringRadius * 0.5}px`,
            fontWeight: 700,
            color: textColor,
            margin: 0,
            lineHeight: 1,
            transition: "none"
          }}>
            {currentCalories.toLocaleString()}
          </h1>
          <span style={{
            fontSize: `${ringRadius * 0.12}px`,
            color: textColor,
            opacity: 0.7,
            letterSpacing: "0.15em",
            textTransform: "uppercase",
            marginTop: `${ringRadius * 0.05}px`,
            fontWeight: 600,
            transition: "none"
          }}>
            {label}
          </span>
          <span style={{
            fontSize: `${ringRadius * 0.08}px`,
            color: accentColor,
            fontWeight: 600,
            marginTop: `${ringRadius * 0.02}px`,
            transition: "none"
          }}>
            KCAL
          </span>
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default CalorieCounter;